import React, { useState, useEffect, useMemo } from 'react';
import './App.css';
import API_CONFIG from './config/api';
import Login from './components/Login';
import Register from './components/Register';
import Payment from './components/Payment';
import PaymentInstructions from './components/PaymentInstructions';
import AccessCode from './components/AccessCode';
import CodeLoading from './components/CodeLoading';
import UserHeader from './components/UserHeader';
import Landing from './components/Landing';
import CrashForm from './components/CrashForm';
import AnalysisDashboard from './components/AnalysisDashboard';
import PredictionCard from './components/PredictionCard';
import StrategySimulator from './components/StrategySimulator';
import ProfitChart from './components/ProfitChart';
import SimulationTable from './components/SimulationTable';

function App() {
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState('landing'); // 'landing' | 'login' | 'register' | 'payment' | 'pay_instructions' | 'code_loading' | 'accesscode'
  const [payInfo, setPayInfo] = useState(null);
  const [authLoading, setAuthLoading] = useState(false);
  const [analysisData, setAnalysisData] = useState(null);
  const [predictionData, setPredictionData] = useState(null);
  const [simulationData, setSimulationData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [isShrunk, setIsShrunk] = useState(false);
  const [theme, setTheme] = useState('dark');
  const [navOpen, setNavOpen] = useState(false);
  const [isPaid, setIsPaid] = useState(() => localStorage.getItem('isPaid') === '1');
  const [lastPaymentStatus, setLastPaymentStatus] = useState(null); // 'VALIDATED' | 'REJECTED' | null
  const [lastPaymentTx, setLastPaymentTx] = useState(null);
  const [globalNotice, setGlobalNotice] = useState('');

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', 'dark');
  }, []);

  // Ecoute la demande d'instructions de paiement depuis Payment.js
  useEffect(() => {
    const handler = (e) => {
      setPayInfo(e.detail);
      setAuthMode('pay_instructions');
    };
    window.addEventListener('payment_instructions', handler);
    return () => window.removeEventListener('payment_instructions', handler);
  }, []);

  // Mobile scroll outline reveal
  useEffect(() => {
    const isMobile = window.matchMedia('(max-width: 768px)').matches;
    if (!isMobile) return;
    const selectors = [
      '.feature-card', '.usecase-card', '.newsletter-card', '.testimonial-card', '.price-card',
      '.hero-stat', '.resource-card', '.step-card', '.stat-card', '.prediction-card', '.strategy-simulator',
      '.simulation-results', '.simulation-table', '.auth-card', '.payment-container', '.plan-card'
    ];
    const nodes = Array.from(document.querySelectorAll(selectors.join(',')));
    if (!nodes.length) return;
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting) {
          e.target.classList.add('outlined');
        } else {
          e.target.classList.remove('outlined');
        }
      });
    }, { root: null, threshold: 0.25 });
    nodes.forEach(n => io.observe(n));
    return () => io.disconnect();
  }, [authMode, user]);

  const t = useMemo(() => ({
    brand: 'BetAI',
    nav: { features: 'Fonctionnalités', usecases: "Cas d'usage", pricing: 'Tarifs', faq: 'FAQ' },
    hero: { ctaCreate: 'Créer mon compte gratuit', ctaLogin: 'Me connecter' }
  }), []);

  // Vérification de l'authentification au chargement
  useEffect(() => {
    checkAuth();
  }, []);

  // Scrollspy + scroll fluide pour la navbar sur la landing
  useEffect(() => {
    if (user || authMode !== 'landing') return;
    const links = Array.from(document.querySelectorAll('#nav-links a'));
    // Eco listener analytics example: log to console (remplaçable par envoi API)
    const analyticsListener = (e) => {
      const detail = e.detail || {};
      // Placeholder: brancher vers votre backend plus tard
      /* eslint-disable */console.log(...oo_oo(`1368646903_94_6_94_40_4`,'[analytics]', detail));
    };
    window.addEventListener('analytics', analyticsListener);
    const handler = () => {
      const sections = ['features','usecases','pricing','faq'];
      let active = '';
      for (const id of sections) {
        const el = document.getElementById(id);
        if (!el) continue;
        const rect = el.getBoundingClientRect();
        if (rect.top <= 120 && rect.bottom >= 120) { active = id; break; }
      }
      links.forEach(a => a.classList.toggle('active', a.dataset.target === active));
    };
    const clickSmooth = (e) => {
      const anchor = e.target.closest('a[href^="#"]');
      if (!anchor) return;
      const id = anchor.getAttribute('href').slice(1);
      const el = document.getElementById(id);
      if (el) {
        e.preventDefault();
        const y = el.getBoundingClientRect().top + window.pageYOffset - 72;
        window.scrollTo({ top: y, behavior: 'smooth' });
      }
    };
    window.addEventListener('scroll', handler, { passive: true });
    document.getElementById('nav-links')?.addEventListener('click', clickSmooth);
    handler();
    return () => {
      window.removeEventListener('scroll', handler);
      document.getElementById('nav-links')?.removeEventListener('click', clickSmooth);
      window.removeEventListener('analytics', analyticsListener);
    };
  }, [user, authMode]);

  // Shrink header on scroll
  useEffect(() => {
    if (authMode !== 'landing' || user) return;
    const onScroll = () => {
      setIsShrunk(window.scrollY > 10);
      // Analytics profondeur de scroll (25/50/75/90)
      const h = document.documentElement.scrollHeight - window.innerHeight;
      const y = window.scrollY;
      const p = Math.floor((y / Math.max(1, h)) * 100);
      const marks = [25,50,75,90];
      for (const m of marks) {
        const key = `scroll_${m}`;
        if (p >= m && !sessionStorage.getItem(key)) {
          sessionStorage.setItem(key, '1');
          window.dispatchEvent(new CustomEvent('analytics', { detail: { type: 'scroll_depth', value: m } }));
        }
      }
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener('scroll', onScroll);
  }, [authMode, user]);

  const checkAuth = async () => {
    try {
              const response = await fetch(`${API_CONFIG.BASE_URL}${API_CONFIG.ENDPOINTS.CHECK_AUTH}`, {
        credentials: 'include'
      });
      
      if (response.ok) {
        const data = await response.json();
        setUser(data.user);
        if (typeof data.user?.is_paid !== 'undefined') {
          const paid = !!data.user.is_paid;
          setIsPaid(paid);
          localStorage.setItem('isPaid', paid ? '1' : '0');
        }
        if (typeof data.user?.last_payment_status !== 'undefined') {
          const status = data.user.last_payment_status || null;
          setLastPaymentStatus(status);
          setLastPaymentTx(data.user.last_payment_tx || null);
          if (status === 'REJECTED') {
            setGlobalNotice("Votre paiement a été rejeté. Veuillez réessayer avec un ID valide.");
            setAuthMode('payment');
          } else if (status === 'VALIDATED' && !isPaid) {
            // Si le paiement est validé, activer directement l'utilisateur
            setIsPaid(true);
            localStorage.setItem('isPaid', '1');
            setGlobalNotice("Paiement validé avec succès ! Redirection vers l'application...");
            // Rediriger vers l'application principale
            setAuthMode('main');
            // Nettoyer le message après 3 secondes
            setTimeout(() => setGlobalNotice(''), 3000);
          }
        }
      }
    } catch (err) {
      /* eslint-disable */console.log(...oo_oo(`1368646903_186_6_186_45_4`,'Utilisateur non connecté'));
    }
  };

  // Rafraîchit périodiquement l'état de paiement tant que l'utilisateur n'est pas payé
  useEffect(() => {
    if (!user || isPaid) return;
    const id = setInterval(() => { checkAuth(); }, 20000);
    const onFocus = () => checkAuth();
    window.addEventListener('focus', onFocus);
    return () => { clearInterval(id); window.removeEventListener('focus', onFocus); };
  }, [user, isPaid]);

  const handleGoHome = async () => {
    try {
              await fetch(`${API_CONFIG.BASE_URL}${API_CONFIG.ENDPOINTS.LOGOUT}`, { method: 'POST', credentials: 'include' });
    } catch (e) { /* ignore */ }
    setUser(null);
    setAuthMode('landing');
    localStorage.removeItem('isPaid');
  };

  const handleLogin = (userData) => {
    setUser(userData);
    // Redirige vers l'application principale après connexion
    setAuthMode('main');
  };

  const handleLogout = () => {
    setUser(null);
    setAnalysisData(null);
    setPredictionData(null);
    setSimulationData(null);
  };

  const handleCrashSubmit = async (crashHistory, aiMode = 'equilibre') => {
    setLoading(true);
    setError(null);
    
    try {
      /* eslint-disable */console.log(...oo_oo(`1368646903_226_6_226_98_4`,'Envoi des données de crash:', { crash_history: crashHistory, ai_mode: aiMode }));
      
      const response = await fetch(`${API_CONFIG.BASE_URL}${API_CONFIG.ENDPOINTS.PREDICT}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ crash_history: crashHistory, ai_mode: aiMode })
      });
      
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Erreur HTTP: ${response.status}`);
      }
      
      const data = await response.json();
      /* eslint-disable */console.log(...oo_oo(`1368646903_241_6_241_41_4`,'Réponse reçue:', data));
      
      setAnalysisData(data.statistics);
      setPredictionData(data.prediction);
    } catch (err) {
      /* eslint-disable */console.error(...oo_tx(`1368646903_246_6_246_54_11`,'Erreur lors de l\'analyse:', err));
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSimulation = async (simulationParams) => {
    setLoading(true);
    setError(null);
    
    try {
      /* eslint-disable */console.log(...oo_oo(`1368646903_258_6_258_74_4`,'Envoi des paramètres de simulation:', simulationParams));
      
      const response = await fetch(`${API_CONFIG.BASE_URL}${API_CONFIG.ENDPOINTS.SIMULATE}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          crash_history: simulationParams.crashHistory,
          initial_bet: simulationParams.initialBet,
          target_multiplier: simulationParams.targetMultiplier,
          num_rounds: simulationParams.numRounds,
          strategy_type: simulationParams.strategyType
        })
      });
      
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Erreur HTTP: ${response.status}`);
      }
      
      const data = await response.json();
      /* eslint-disable */console.log(...oo_oo(`1368646903_279_6_279_55_4`,'Réponse de simulation reçue:', data));
      
      setSimulationData(data.simulation);
    } catch (err) {
      /* eslint-disable */console.error(...oo_tx(`1368646903_283_6_283_57_11`,'Erreur lors de la simulation:', err));
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // Si l'utilisateur n'est pas connecté, afficher l'authentification / landing
  if (!user) {
    if (authMode === 'landing') {
      return (
        <div className="app">
          <header className={`app-header ${isShrunk ? 'shrunk' : ''}`}>
            <div className="nav-inner">
              <div className="brand">
                <img
                  src="/logos/BetAi.png"
                  alt="BetAi logo"
                  className="brand-logo-img"
                  loading="eager"
                  width="28"
                  height="28"
                />
                <span className="brand-text">{t.brand}</span>
              </div>
              <nav className="nav-links" id="nav-links" aria-label="Navigation principale">
                <a href="#features" data-target="features">{t.nav.features}</a>
                <a href="#usecases" data-target="usecases">{t.nav.usecases}</a>
                <a href="#pricing" data-target="pricing">{t.nav.pricing} <span className="badge-new" aria-label="Nouveau">Nouveau</span></a>
                <a href="#faq" data-target="faq">{t.nav.faq}</a>
              </nav>
              <div className="nav-actions">
                <button
                  className={`burger ${navOpen ? 'open' : ''}`}
                  aria-label="Ouvrir le menu"
                  aria-expanded={navOpen}
                  aria-controls="mobile-menu"
                  onClick={() => setNavOpen(!navOpen)}
                >
                  <span></span>
                  <span></span>
                  <span></span>
                </button>
              </div>
            </div>
          </header>
          <main className="app-main">
            <Landing 
              onStartLogin={() => setAuthMode('login')}
              onStartRegister={() => setAuthMode('register')}
            />
          </main>

          {/* Mobile menu */}
          <div id="mobile-menu" className={`mobile-menu ${navOpen ? 'open' : ''}`} role="dialog" aria-modal="true">
            <div className="mobile-backdrop" onClick={() => setNavOpen(false)}></div>
            <aside className="mobile-panel">
              <div className="mobile-header">
                <div className="brand">
                  <img src="/logos/BetAi.png" alt="BetAi" className="brand-logo-img" width="26" height="26" />
                  <span className="brand-text">{t.brand}</span>
                </div>
                <button className="burger open" aria-label="Fermer" onClick={() => setNavOpen(false)}>
                  <span></span><span></span><span></span>
                </button>
              </div>
              <nav className="mobile-links" id="mobile-links" onClick={() => setNavOpen(false)}>
                <a href="#features" data-target="features">{t.nav.features}</a>
                <a href="#usecases" data-target="usecases">{t.nav.usecases}</a>
                <a href="#pricing" data-target="pricing">{t.nav.pricing} <span className="badge-new" aria-label="Nouveau">Nouveau</span></a>
                <a href="#faq" data-target="faq">{t.nav.faq}</a>
              </nav>
              <div className="mobile-ctas">
                <button className="btn-primary-small" onClick={() => { setNavOpen(false); setAuthMode('register'); }}>Créer un compte</button>
                <button className="btn-ghost-small" onClick={() => { setNavOpen(false); setAuthMode('login'); }}>Se connecter</button>
              </div>
            </aside>
          </div>
        </div>
      );
    }
    
    return (
      <div className="app">
        {authMode === 'login' ? (
          <Login 
            onLogin={handleLogin}
            onSwitchToRegister={() => setAuthMode('register')}
            onGoHome={handleGoHome}
            loading={authLoading}
          />
        ) : (
          <Register 
            onRegister={() => setAuthMode('login')}
            onSwitchToLogin={() => setAuthMode('login')}
            onGoHome={handleGoHome}
            loading={authLoading}
          />
        )}
      </div>
    );
  }

  // Application principale pour les utilisateurs connectés
  if (authMode === 'pay_instructions') {
    return (
      <PaymentInstructions 
        user={user} 
        info={payInfo} 
        onSent={() => {
          // L'utilisateur sera redirigé automatiquement après validation admin
          // via le composant PaymentInstructions qui vérifie le statut
        }} 
        onCancel={() => setAuthMode('login')} 
      />
    );
  }

  if (authMode === 'code_loading') {
    return (
      <CodeLoading onComplete={() => setAuthMode('main')} />
    );
  }

  if (authMode === 'accesscode') {
    return (
      <AccessCode 
        notice={`Paiement validé. Entrez le code reçu par email${lastPaymentTx ? ` (ID: ${lastPaymentTx})` : ''} pour activer votre accès.`}
        onActivated={() => { setIsPaid(true); localStorage.setItem('isPaid','1'); setAuthMode('main'); }} 
        onCancel={() => setAuthMode('login')} 
      />
    );
  }

  if (authMode === 'payment' || (user && !isPaid)) {
    return (
      <Payment 
        user={user} 
        notice={globalNotice} 
        lastPaymentStatus={lastPaymentStatus}
        lastPaymentTx={lastPaymentTx}
        onComplete={() => { 
          setIsPaid(true); 
          localStorage.setItem('isPaid','1'); 
          setAuthMode('main'); 
        }} 
        onGoHome={handleGoHome} 
      />
    );
  }

  // Application principale (tests et analyses)
  if (authMode === 'main' || (user && isPaid)) {
    return (
      <div className="app">
        <UserHeader user={user} onLogout={handleLogout} onHomeClick={handleGoHome} />
        <main className="app-main">
          <div className="container">
            <CrashForm onSubmit={handleCrashSubmit} loading={loading} />
            
            {error && (
              <div className="error-message">
                <p>{error}</p>
              </div>
            )}

            {analysisData && (
              <AnalysisDashboard data={analysisData} />
            )}

            {predictionData && (
              <PredictionCard prediction={predictionData} />
            )}

            {analysisData && (
              <StrategySimulator 
                crashHistory={analysisData.crash_data || Array.from({length: 5}, (_, i) => 1.5 + i * 0.5)}
                onSimulate={handleSimulation}
                loading={loading}
              />
            )}

            {simulationData && (
              <div className="simulation-results">
                <h3>Résultats de la Simulation</h3>
                
                {/* Graphique des gains */}
                <ProfitChart simulationData={simulationData} />
                
                {/* Tableau détaillé */}
                <SimulationTable simulationData={simulationData} />
                
                {/* Résumé des statistiques */}
                <div className="stats-grid">
                  <div className="stat-card">
                    <h4>Profit Total</h4>
                    <p className={simulationData.statistics.total_profit >= 0 ? 'positive' : 'negative'}>
                      {simulationData.statistics.total_profit} FCFA
                    </p>
                  </div>
                  <div className="stat-card">
                    <h4>Taux de Réussite</h4>
                    <p>{(simulationData.statistics.win_rate * 100).toFixed(1)}%</p>
                  </div>
                  <div className="stat-card">
                    <h4>ROI</h4>
                    <p className={simulationData.statistics.roi >= 0 ? 'positive' : 'negative'}>
                      {simulationData.statistics.roi}%
                    </p>
                  </div>
                  <div className="stat-card">
                    <h4>Gain Max</h4>
                    <p className="positive">{simulationData.statistics.max_profit} FCFA</p>
                  </div>
                  <div className="stat-card">
                    <h4>Perte Max</h4>
                    <p className="negative">{simulationData.statistics.min_profit} FCFA</p>
                  </div>
                  <div className="stat-card">
                    <h4>Tours Joués</h4>
                    <p>{simulationData.statistics.total_rounds}</p>
                  </div>
                </div>
              </div>
            )}
          </div>
        </main>
      </div>
    );
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="header-content">
          <div className="brand" style={{display:'inline-flex',alignItems:'center',gap:'8px'}}>
            <img src="/logos/BetAi.png" alt="BetAi" className="brand-logo-img" width="26" height="26" />
            <span className="brand-text">{t.brand}</span>
          </div>
          <div className="header-left">
            <h1>BetAi - Module Aviator</h1>
            <span className={`plan-badge ${isPaid ? 'active' : 'inactive'}`}>{isPaid ? 'Plan actif' : 'Plan inactif'}</span>
            <p>Analyse intelligente et prédiction des crashs</p>
          </div>
          <div>
            <button className="theme-toggle btn-home" onClick={handleGoHome}>Aller à l'accueil</button>
          </div>
          <UserHeader user={user} onLogout={handleLogout} onHomeClick={handleGoHome} />
        </div>
      </header>

      <main className="app-main">
        <div className="container">
          <CrashForm onSubmit={handleCrashSubmit} loading={loading} />
          
          {error && (
            <div className="error-message">
              <p>{error}</p>
            </div>
          )}

          {analysisData && (
            <AnalysisDashboard data={analysisData} />
          )}

          {predictionData && (
            <PredictionCard prediction={predictionData} />
          )}

          {analysisData && (
            <StrategySimulator 
              crashHistory={analysisData.total_crashes ? Array.from({length: 5}, (_, i) => 1.5 + i * 0.5) : []}
              onSimulate={handleSimulation}
              loading={loading}
            />
          )}

          {simulationData && (
            <div className="simulation-results">
              <h3>Résultats de la Simulation</h3>
              
              {/* Graphique des gains */}
              <ProfitChart simulationData={simulationData} />
              
              {/* Tableau détaillé */}
              <SimulationTable simulationData={simulationData} />
              
              {/* Résumé des statistiques */}
              <div className="stats-grid">
                <div className="stat-card">
                  <h4>Profit Total</h4>
                  <p className={simulationData.statistics.total_profit >= 0 ? 'positive' : 'negative'}>
                    {simulationData.statistics.total_profit} FCFA
                  </p>
                </div>
                <div className="stat-card">
                  <h4>Taux de Réussite</h4>
                  <p>{(simulationData.statistics.win_rate * 100).toFixed(1)}%</p>
                </div>
                <div className="stat-card">
                  <h4>ROI</h4>
                  <p className={simulationData.statistics.roi >= 0 ? 'positive' : 'negative'}>
                    {simulationData.statistics.roi}%
                  </p>
                </div>
                <div className="stat-card">
                  <h4>Gain Max</h4>
                  <p className="positive">{simulationData.statistics.max_profit} FCFA</p>
                </div>
                <div className="stat-card">
                  <h4>Perte Max</h4>
                  <p className="negative">{simulationData.statistics.min_profit} FCFA</p>
                </div>
                <div className="stat-card">
                  <h4>Tours Joués</h4>
                  <p>{simulationData.statistics.total_rounds}</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

export default App;
